Here's a JavaScript function that takes a string as input and wraps it at 80 characters:

```javascript
function wrapStringAt80Chars(str) {
  const wrappedString = str
    .split(' ')
    .map((word, index, array) => {
      if (word.length + (index + 1) <= 80) {
        return word;
      } else {
        return word.substring(0, 80 - array.length - 1) + '\n' + array.slice(array.length - 1, array.length).join(' ');
      }
    })
    .join(' ');

  return wrappedString;
}
```

