// Get the search query input element
const searchQueryInput = document.getElementById("search-query-input");

// Get the properties container element
const propertiesContainer = document.getElementById("properties-container");

// Add an event listener to the search query input element
searchQueryInput.addEventListener("input", searchProperties);

// Search for properties when the search query input element changes
function searchProperties() {
  const searchQuery = searchQueryInput.value.toLowerCase();
  let filteredProperties = propertiesContainer.getElementsByClassName("property-card");

  // Show all properties if the search query is empty
  if (searchQuery === "") {
    filteredProperties = propertiesContainer.getElementsByTagName("div");
  }

  // Filter the properties based on the search query
  for (let i = 0; i < filteredProperties.length; i++) {
    const property = filteredProperties[i];
    const propertyAddress = property.getElementsByTagName("p")[0];
    if (propertyAddress.textContent.toLowerCase().includes(searchQuery)) {
      property.style.display = "block";
    } else {
      property.style.display = "none";
    }
  }
}

// Add an event listener to the view details button
propertiesContainer.addEventListener("click", (event) => {
  if (event.target.classList.contains("view-details")) {
    const propertyId = event.target.dataset.propertyId;
    const property = propertiesContainer.getElementsByTagName("div")[propertyId];
    property.style.backgroundColor = "white";
    property.style.borderColor = "none";
  }
});

// Remove the view details button click event listener when the property is no longer showing
propertiesContainer.addEventListener("click", (event) => {
  if (event.target.classList.contains("view-details")) {
    const propertyId = event.target.dataset.propertyId;
    const property = propertiesContainer.getElementsByTagName("div")[propertyId];
    property.style.backgroundColor = "#f2f2f2";
    property.style.borderColor = "1px solid #333";
  }
});
```

