```
function quakeToCSGO(sensitivity) {
  // Quake Champions uses a 50% output when you hit 1.0, so we need to correct for that
  sensitivity = sensitivity / 2;

  // Quake Champions uses a linear mapping, while CS:GO uses a non-linear mapping
  // We need to perform a non-linear mapping to match CS:GO's sensitivity curve
  const linear = sensitivity / 400;
  const nonlinear = linear * (0.125 + 0.875 * Math.tanh(linear / 2));

  // CS:GO has a minimum sensitivity of 0.4 and a maximum sensitivity of 0.65
  // We need to scale the sensitivity to fit within this range
  const minSensitivity = 0.4;
  const maxSensitivity = 0.65;
  const sens = (nonlinear - minSensitivity) / (maxSensitivity - minSensitivity);

  // And finally, we need to apply a correction factor to match CS:GO's sensitivity curve
  const correctionFactor = 1.6;

  return sens * correctionFactor;
}
```
