void loop() {
  // Read raw accelerometer values from the device
  int raw_x = analogRead(ACC_X_PIN);
  int raw_y = analogRead(ACC_Y_PIN);
  int raw_z = analogRead(ACC_Z_PIN);

  // Calculate force in g's for each axis
  float force_x = (raw_x - 512) / 1023.0 * 9.8;
  float force_y = (raw_y - 512) / 1023.0 * 9.8;
  float force_z = (raw_z - 512) / 1023.0 * 9.8;

  // Check for shock events that exceed 5g's on any axis
  if (fabs(force_x) > 5.0 || fabs(force_y) > 5.0 || fabs(force_z) > 5.0) {
    // Get current time in milliseconds
    unsigned long time = millis();

    // Create message to publish through the Particle cloud
