    String time_str = String(time);
    String force_str_x = String(fabs(force_x));
    String force_str_y = String(fabs(force_y));
    String force_str_z = String(fabs(force_z));
    snprintf(message, sizeof(message), "Shock event at %u ms: X-axis: %.2f g's, Y-axis: %.2f g's, Z-axis: %.2f g's", time, force_x, force_y, force_z);
    Serial.println(message);

    // Publish message through the Particle cloud
    Particle.publish("accelerometer_shock", message);
  }

  // Wait for 1000ms (1 second) before checking again
  delay(1000);
}
