    MaxHeap() {}

    // Adds an element to the heap
    void push(int value) {
        // Check if the vector is full
        if (data.size() == capacity) {
            std::cerr << "Heap is full, cannot push more elements." << std::endl;
            return;
        }
        data.push_back(value);
        int index = data.size() - 1;
        while (index > 0) {
            int parentIndex = (index - 1) / 2;
            if (data[index] > data[parentIndex]) {
                std::swap(data[index], data[parentIndex]);
                index = parentIndex;
            } else {
                break;
            }
        }
    }

    // Removes the root element from the heap
    int pop() {
        if (data.empty()) {
            std::cerr << "Heap is empty, cannot pop element." << std::endl;
            return -1;
        }
        int root = data[0];
        data[0] = data[data.size() - 1];
        data.pop_back();
        maxHeapify(0);
        return root;
    }

    // Helper method to maintain heap property
    void maxHeapify(int index) {
        int leftIndex = 2 * index + 1;
        int rightIndex = 2 * index + 2;
        int largestIndex = index;
        if (leftIndex < data.size() && data[leftIndex] > data[largestIndex]) {
            largestIndex = leftIndex;
        }
        if (rightIndex < data.size() && data[rightIndex] > data[largestIndex]) {
            largestIndex = rightIndex;
        }
        if (largestIndex != index) {
            std::swap(data[index], data[largestIndex]);
            maxHeapify(largestIndex);
        }
    }

    // Gets the size of the heap
    int size() const {
        return data.size();
    }

    // Checks if the heap is empty
    bool empty() const {
        return data.empty();
    }

private:
    std::vector<int> data;
    int capacity;
};
```
