import React, { useState } from 'react';
import Draggable from 'react-draggable';

const AnnotationDraggable = () => {
  const [annotations, setAnnotations] = useState([
    { x: 100, y: 100, width: 200, height: 200 },
    { x: 300, y: 200, width: 200, height: 200 },
  ]);

  const handleDrop = ( dragInfo ) => {
    setAnnotations([
      ...annotations.map((a, i) => i !== dragInfo.drag_index ? a : { ...a, ...dragInfo }),
      ...annotations.filter((a, i) => i === dragInfo.drag_index)
    ]);
  };

  return (
    <div>
      {annotations.map((annotation, index) => (
        <Draggable key={index} handle={index} draggableClassName="annotator">
          <div
            className="annotator"
            style={{
              left: annotation.x,
              top: annotation.y,
              width: annotation.width,
              height: annotation.height,
            }}
          />
        </Draggable>
      ))}
    </div>
  );
};

export default AnnotationDraggable;
```
