Here is a simple example of a reusable barrier synchronization using C++ and the C++ Standard Library:
```
#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>

// Define the barrier counter
std::atomic unsigned int barrier_count = 0;

// Define the barrier lock
std::mutex barrier_lock;

// Define the barrier condition variable
std::condition_variable barrier_cv;

// Define the barrier synchronization function
void barriere(std::atomic unsigned int& count, std::mutex& lock, std::condition_variable& cv) {
    // Increment the barrier counter
    ++count;

    // Wait for all other threads to reach the barrier
    lock_guard<mutex> lock(lock);
    cv.wait(lock, [this, &lock, &cv] {
        return atomic_load_explicit(&count, memory_order_relaxed) == (barriere_count + 1);
    });

    // Release the lock and decrement the barrier counter
    lock.unlock();
    --count;

    // Notify all blocked threads
    cv.notify_all();
}

int main() {
    // Create a vector of threads
    std::vector<std::thread> threads;

    // Create 5 threads and add them to the vector
    for (int i = 0; i < 5; ++i) {
        threads.emplace_back(barriere, barrier_count, barrier_lock, barrier_cv);
    }

    // Wait for all threads to finish
    for (auto& thread : threads) {
        thread.join();
    }

    // Print the final value of the barrier counter
    std::cout << "Barrier count: " << barrier_count << std::endl;

    return 0;
}
```
